import{_ as r,o as t,c as o,ag as a}from"./chunks/framework.CAXxHpAX.js";const c=JSON.parse('{"title":"Broker","description":"","frontmatter":{},"headers":[],"relativePath":"prerequisites/broker.md","filePath":"prerequisites/broker.md","lastUpdated":1778435235000}'),i={name:"prerequisites/broker.md"};function s(l,e,n,h,m,p){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="broker" tabindex="-1">Broker <a class="header-anchor" href="#broker" aria-label="Permalink to &quot;Broker&quot;">​</a></h1><p>The broker acts as an intermediary between TheengsGateway and your <a href="/prerequisites/controller.html">controller</a>. Consider it as a centralized hub at the heart of your home automation system. It carries on messages following a publish/subscribe mechanism.</p><p>All the events or commands could pass by the broker.</p><p>There are many choices of brokers, here are some of the most popular:</p><ul><li><a href="https://mosquitto.org/" target="_blank" rel="noreferrer">Mosquitto</a> (open source)</li><li><a href="https://moquette-io.github.io/moquette/" target="_blank" rel="noreferrer">Moquette</a> (open source)</li><li><a href="https://www.hivemq.com/hivemq/features/" target="_blank" rel="noreferrer">HiveMQ</a></li><li>Embedded MQTT brokers (Home Assistant and openHAB)</li></ul><p>This <a href="https://en.wikipedia.org/wiki/Comparison_of_MQTT_implementations" target="_blank" rel="noreferrer">comparison of MQTT implementations</a> on Wikipedia gives you more details about the different choices you have. This <a href="https://github.com/mqtt/mqtt.github.io/wiki/brokers" target="_blank" rel="noreferrer">list of brokers</a> on GitHub seems to be the most exhaustive ones. Here is also a <a href="https://www.hivemq.com/blog/top-10-mqtt-broker-criteria/" target="_blank" rel="noreferrer">list of criteria for selecting a MQTT broker</a> from HiveMQ.</p><p>Once you&#39;ve installed your broker, it can be interesting to see the traffic passing to it and to publish data. There are several tools available to do this:</p><ul><li><a href="http://mqtt-explorer.com/" target="_blank" rel="noreferrer">MQTT Explorer</a></li><li><a href="https://github.com/hivemq/hivemq-mqtt-web-client" target="_blank" rel="noreferrer">HiveMQ MQTT web client</a></li><li><a href="https://mqttfx.jensd.de/" target="_blank" rel="noreferrer">MQTT FX</a></li></ul>',8)])])}const f=r(i,[["render",s]]);export{c as __pageData,f as default};
